export type EventHandler = (payload: any) => void;

export class EventBus {
  private handlers: Map<string, EventHandler[]> = new Map();

  on(eventName: string, handler: EventHandler) {
    if (!this.handlers.has(eventName)) this.handlers.set(eventName, []);
    this.handlers.get(eventName)!.push(handler);
  }

  emit(eventName: string, payload: any) {
    const handlers = this.handlers.get(eventName) || [];
    for (const h of handlers) {
      try {
        h(payload);
      } catch (err) {
        // swallow errors from handlers to avoid crashing emitter
        console.error('Event handler error for', eventName, err);
      }
    }
  }
}

export type User = {
  id: string;
  name: string;
  email: string;
};

export class UserService {
  private users: Map<string, User> = new Map();

  create(user: Omit<User, 'id'> & { id?: string }): User {
    const id = user.id ?? this.generateId();
    const u: User = { id, name: user.name, email: user.email };
    this.users.set(id, u);
    return u;
  }

  getAll(): User[] {
    return Array.from(this.users.values());
  }

  getById(id: string): User | undefined {
    return this.users.get(id);
  }

  update(id: string, data: Partial<Omit<User, 'id'>>): User | undefined {
    const existing = this.users.get(id);
    if (!existing) return undefined;
    const updated = { ...existing, ...data };
    this.users.set(id, updated);
    return updated;
  }

  delete(id: string): boolean {
    return this.users.delete(id);
  }

  private generateId() {
    return Math.random().toString(36).slice(2, 9);
  }
}

export type Project = {
  id: string;
  name: string;
  description?: string;
  members: string[]; // user ids
};

export class ProjectService {
  private projects: Map<string, Project> = new Map();

  create(data: Omit<Project, 'id' | 'members'> & { id?: string; members?: string[] }): Project {
    const id = data.id ?? this.generateId();
    const project: Project = { id, name: data.name, description: data.description ?? '', members: data.members ?? [] };
    this.projects.set(id, project);
    return project;
  }

  getAll(): Project[] {
    return Array.from(this.projects.values());
  }

  getById(id: string): Project | undefined {
    return this.projects.get(id);
  }

  update(id: string, data: Partial<Omit<Project, 'id'>>): Project | undefined {
    const existing = this.projects.get(id);
    if (!existing) return undefined;
    const updated: Project = { ...existing, ...data };
    // ensure members array exists
    updated.members = updated.members ?? [];
    this.projects.set(id, updated);
    return updated;
  }

  delete(id: string): boolean {
    return this.projects.delete(id);
  }

  addMember(projectId: string, userId: string): Project | undefined {
    const p = this.projects.get(projectId);
    if (!p) return undefined;
    if (!p.members.includes(userId)) p.members.push(userId);
    return p;
  }

  removeMember(projectId: string, userId: string): Project | undefined {
    const p = this.projects.get(projectId);
    if (!p) return undefined;
    p.members = p.members.filter((m) => m !== userId);
    this.projects.set(projectId, p);
    return p;
  }

  private generateId() {
    return Math.random().toString(36).slice(2, 9);
  }
}

import { EventBus } from '../event-bus';

export type TaskStatus = 'todo' | 'in-progress' | 'done';

export type Task = {
  id: string;
  title: string;
  description?: string;
  status: TaskStatus;
  assignee?: string; // user id
  projectId: string;
};

export class TaskService {
  private tasks: Map<string, Task> = new Map();
  private allowedTransitions: Record<TaskStatus, TaskStatus[]> = {
    'todo': ['in-progress'],
    'in-progress': ['done'],
    'done': [],
  };

  constructor(private bus: EventBus) {}

  create(data: Omit<Task, 'id' | 'status'> & { id?: string; status?: TaskStatus }): Task {
    const id = data.id ?? this.generateId();
    const status = data.status ?? 'todo';
    const task: Task = { id, title: data.title, description: data.description ?? '', status, assignee: data.assignee, projectId: data.projectId };
    this.tasks.set(id, task);
    this.bus.emit('task.created', task);
    return task;
  }

  getAll(filter?: { projectId?: string }): Task[] {
    let arr = Array.from(this.tasks.values());
    if (filter?.projectId) arr = arr.filter((t) => t.projectId === filter.projectId);
    return arr;
  }

  getById(id: string): Task | undefined {
    return this.tasks.get(id);
  }

  update(id: string, data: Partial<Omit<Task, 'id' | 'projectId'>>): Task | undefined {
    const existing = this.tasks.get(id);
    if (!existing) return undefined;
    const updated: Task = { ...existing, ...data };
    this.tasks.set(id, updated);
    this.bus.emit('task.updated', updated);
    return updated;
  }

  delete(id: string): boolean {
    const existed = this.tasks.delete(id);
    if (existed) this.bus.emit('task.deleted', { id });
    return existed;
  }

  setStatus(id: string, newStatus: TaskStatus): Task | undefined {
    const task = this.tasks.get(id);
    if (!task) return undefined;
    if (task.status === newStatus) return task;
    const allowed = this.allowedTransitions[task.status] || [];
    if (!allowed.includes(newStatus)) throw new Error(`Invalid status transition from ${task.status} to ${newStatus}`);
    task.status = newStatus;
    this.tasks.set(id, task);
    this.bus.emit('task.status_changed', task);
    return task;
  }

  assign(id: string, userId: string | undefined): Task | undefined {
    const task = this.tasks.get(id);
    if (!task) return undefined;
    task.assignee = userId;
    this.tasks.set(id, task);
    this.bus.emit('task.assigned', task);
    return task;
  }

  private generateId() {
    return Math.random().toString(36).slice(2, 9);
  }
}

import { EventBus } from '../event-bus';

export type Comment = {
  id: string;
  taskId: string;
  authorId: string;
  body: string;
  createdAt: string; // ISO
};

export class CommentService {
  private comments: Map<string, Comment> = new Map();

  constructor(private bus: EventBus) {}

  create(data: Omit<Comment, 'id' | 'createdAt'> & { id?: string }): Comment {
    const id = data.id ?? this.generateId();
    const createdAt = new Date().toISOString();
    const comment: Comment = { id, taskId: data.taskId, authorId: data.authorId, body: data.body, createdAt };
    this.comments.set(id, comment);
    this.bus.emit('comment.added', comment);
    return comment;
  }

  getAll(filter?: { taskId?: string }): Comment[] {
    let arr = Array.from(this.comments.values());
    if (filter?.taskId) arr = arr.filter((c) => c.taskId === filter.taskId);
    return arr;
  }

  getById(id: string): Comment | undefined {
    return this.comments.get(id);
  }

  delete(id: string): boolean {
    const existed = this.comments.delete(id);
    if (existed) this.bus.emit('comment.deleted', { id });
    return existed;
  }

  private generateId() {
    return Math.random().toString(36).slice(2, 9);
  }
}

import { EventBus } from '../event-bus';

export type Notification = {
  id: string;
  userId: string;
  message: string;
  read: boolean;
  createdAt: string;
};

export class NotificationService {
  private notifications: Map<string, Notification> = new Map();

  constructor(private bus: EventBus) {
    // subscribe to events
    this.bus.on('task.assigned', (payload) => this.onTaskAssigned(payload));
    this.bus.on('comment.added', (payload) => this.onCommentAdded(payload));
    this.bus.on('task.status_changed', (payload) => this.onTaskStatusChanged(payload));
  }

  getAll(filter?: { userId?: string }): Notification[] {
    let arr = Array.from(this.notifications.values());
    if (filter?.userId) arr = arr.filter((n) => n.userId === filter.userId);
    return arr;
  }

  markRead(id: string): Notification | undefined {
    const n = this.notifications.get(id);
    if (!n) return undefined;
    n.read = true;
    this.notifications.set(id, n);
    return n;
  }

  private notify(userId: string, message: string) {
    const id = this.generateId();
    const n: Notification = { id, userId, message, read: false, createdAt: new Date().toISOString() };
    this.notifications.set(id, n);
  }

  private onTaskAssigned(payload: any) {
    const task = payload as any;
    if (task.assignee) {
      this.notify(task.assignee, `You were assigned task ${task.title} (id: ${task.id})`);
    }
  }

  private onCommentAdded(payload: any) {
    const comment = payload as any;
    // We don't have direct access to task service here; assume payload includes task info? spec says Notification Service should create notification for task's assignee.
    // Since services don't call each other, the CommentService will include only comment. To find assignee, the router orchestration should emit a richer event.
    // However we can attempt to handle if payload.taskAssignee exists
    if (comment.taskAssignee) {
      // avoid notifying the commenter
      if (comment.taskAssignee !== comment.authorId) {
        this.notify(comment.taskAssignee, `New comment on task ${comment.taskId} by ${comment.authorId}: ${comment.body}`);
      }
    }
  }

  private onTaskStatusChanged(payload: any) {
    const task = payload as any;
    if (task.assignee) {
      this.notify(task.assignee, `Status of task ${task.title} changed to ${task.status}`);
    }
  }

  private generateId() {
    return Math.random().toString(36).slice(2, 9);
  }
}

import { IncomingMessage, ServerResponse } from 'http';
import { UserService } from './services/user-service';
import { ProjectService } from './services/project-service';
import { TaskService } from './services/task-service';
import { CommentService } from './services/comment-service';
import { NotificationService } from './services/notification-service';
import { EventBus } from './event-bus';

function parseUrlPath(url: string): { pathname: string; query: Record<string, string> } {
  const [path, q] = url.split('?');
  const query: Record<string, string> = {};
  if (q) {
    for (const part of q.split('&')) {
      const [k, v] = part.split('=');
      query[decodeURIComponent(k)] = decodeURIComponent(v || '');
    }
  }
  return { pathname: path, query };
}

export class Router {
  constructor(
    private bus: EventBus,
    private users: UserService,
    private projects: ProjectService,
    private tasks: TaskService,
    private comments: CommentService,
    private notifications: NotificationService
  ) {}

  async handle(req: IncomingMessage, res: ServerResponse) {
    const method = req.method || 'GET';
    const url = req.url || '/';
    const { pathname, query } = parseUrlPath(url);

    res.setHeader('Content-Type', 'application/json');

    try {
      if (pathname === '/users' && method === 'GET') {
        return this.ok(res, this.users.getAll());
      }
      if (pathname === '/users' && method === 'POST') {
        const body = await this.readJson(req);
        const u = this.users.create(body);
        return this.created(res, u);
      }
      if (pathname.startsWith('/users/') ) {
        const id = pathname.split('/')[2];
        if (method === 'GET') return this.ok(res, this.users.getById(id));
        if (method === 'PUT') {
          const body = await this.readJson(req);
          const updated = this.users.update(id, body);
          return this.ok(res, updated);
        }
        if (method === 'DELETE') {
          const del = this.users.delete(id);
          return this.ok(res, { deleted: del });
        }
      }

      // Projects
      if (pathname === '/projects' && method === 'GET') return this.ok(res, this.projects.getAll());
      if (pathname === '/projects' && method === 'POST') {
        const body = await this.readJson(req);
        const p = this.projects.create(body);
        return this.created(res, p);
      }
      if (pathname.startsWith('/projects/')) {
        const parts = pathname.split('/').filter(Boolean);
        const id = parts[1];
        if (parts.length === 2) {
          if (method === 'GET') return this.ok(res, this.projects.getById(id));
          if (method === 'PUT') {
            const body = await this.readJson(req);
            return this.ok(res, this.projects.update(id, body));
          }
          if (method === 'DELETE') return this.ok(res, { deleted: this.projects.delete(id) });
        }
        if (parts.length === 3 && parts[2] === 'members') {
          if (method === 'POST') {
            const body = await this.readJson(req);
            return this.ok(res, this.projects.addMember(id, body.userId));
          }
          if (method === 'DELETE') {
            const body = await this.readJson(req);
            return this.ok(res, this.projects.removeMember(id, body.userId));
          }
        }
      }

      // Tasks
      if (pathname === '/tasks' && method === 'GET') {
        const projectId = query['projectId'];
        return this.ok(res, this.tasks.getAll(projectId ? { projectId } : undefined));
      }
      if (pathname === '/tasks' && method === 'POST') {
        const body = await this.readJson(req);
        const t = this.tasks.create(body);
        return this.created(res, t);
      }
      if (pathname.startsWith('/tasks/')) {
        const parts = pathname.split('/').filter(Boolean);
        const id = parts[1];
        if (parts.length === 2) {
          if (method === 'GET') return this.ok(res, this.tasks.getById(id));
          if (method === 'PUT') {
            const body = await this.readJson(req);
            return this.ok(res, this.tasks.update(id, body));
          }
          if (method === 'DELETE') return this.ok(res, { deleted: this.tasks.delete(id) });
        }
        if (parts.length === 3 && parts[2] === 'status' && method === 'PUT') {
          const body = await this.readJson(req);
          try {
            const updated = this.tasks.setStatus(id, body.status);
            return this.ok(res, updated);
          } catch (err: any) {
            return this.error(res, 400, err.message);
          }
        }
        if (parts.length === 3 && parts[2] === 'assign' && method === 'PUT') {
          const body = await this.readJson(req);
          const updated = this.tasks.assign(id, body.userId);
          return this.ok(res, updated);
        }
      }

      // Comments
      if (pathname === '/comments' && method === 'GET') {
        const taskId = query['taskId'];
        return this.ok(res, this.comments.getAll(taskId ? { taskId } : undefined));
      }
      if (pathname === '/comments' && method === 'POST') {
        const body = await this.readJson(req);
        // We want to include task assignee info in the event so notifications can be created.
        const comment = this.comments.create(body);
        // find task and include assignee in event via bus emit directly here
        const task = this.tasks.getById(comment.taskId);
        const payload: any = { ...comment };
        if (task) payload.taskAssignee = task.assignee;
        // also include task title maybe
        if (task) payload.taskTitle = task.title;
        // emit enriched event
        this.bus.emit('comment.added', payload);
        return this.created(res, comment);
      }
      if (pathname.startsWith('/comments/')) {
        const id = pathname.split('/')[2];
        if (method === 'GET') return this.ok(res, this.comments.getById(id));
        if (method === 'DELETE') return this.ok(res, { deleted: this.comments.delete(id) });
      }

      // Notifications
      if (pathname === '/notifications' && method === 'GET') {
        const userId = query['userId'];
        return this.ok(res, this.notifications.getAll(userId ? { userId } : undefined));
      }
      if (pathname.startsWith('/notifications/')) {
        const id = pathname.split('/')[2];
        if (pathname.endsWith('/read') || pathname.endsWith('/read/')) {
          // path like /notifications/:id/read handled as single segment
        }
        if (req.method === 'PUT' && pathname.endsWith('/read')) {
          const n = this.notifications.markRead(id);
          return this.ok(res, n);
        }
      }

      return this.notFound(res);
    } catch (err: any) {
      return this.error(res, 500, err.message || String(err));
    }
  }

  private async readJson(req: IncomingMessage) {
    const chunks: Uint8Array[] = [];
    for await (const chunk of req) chunks.push(chunk as Uint8Array);
    const str = Buffer.concat(chunks).toString('utf8');
    if (!str) return {};
    return JSON.parse(str);
  }

  private ok(res: ServerResponse, data: any) {
    res.statusCode = 200;
    res.end(JSON.stringify(data));
  }
  private created(res: ServerResponse, data: any) {
    res.statusCode = 201;
    res.end(JSON.stringify(data));
  }
  private notFound(res: ServerResponse) {
    res.statusCode = 404;
    res.end(JSON.stringify({ error: 'not found' }));
  }
  private error(res: ServerResponse, code: number, message: string) {
    res.statusCode = code;
    res.end(JSON.stringify({ error: message }));
  }
}

import http from 'http';
import { EventBus } from './event-bus';
import { UserService } from './services/user-service';
import { ProjectService } from './services/project-service';
import { TaskService } from './services/task-service';
import { CommentService } from './services/comment-service';
import { NotificationService } from './services/notification-service';
import { Router } from './router';

const bus = new EventBus();
const users = new UserService();
const projects = new ProjectService();
const tasks = new TaskService(bus);
const comments = new CommentService(bus);
const notifications = new NotificationService(bus);

const router = new Router(bus, users, projects, tasks, comments, notifications);

const server = http.createServer((req, res) => router.handle(req, res));

const port = process.env.PORT ? Number(process.env.PORT) : 3000;
server.listen(port, () => {
  console.log(`Server started on http://localhost:${port}`);
});

